 "content": "from collections import deque


def transform(grid):
    """Slide each same-color 4-connected object right until blocked."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append({"color": color, "cells": cells, "dx": 0})

    # Advance rightmost objects first so trailing objects can follow into
    # newly opened space, while preserving each object's shape.
    changed = True
    while changed:
        changed = False
        objects.sort(key=lambda obj: max(c for _, c in obj["cells"]) + obj["dx"], reverse=True)
        for i, obj in enumerate(objects):
            candidate = {(r, c + obj["dx"] + 1) for r, c in obj["cells"]}
            if any(c >= w for _, c in candidate):
                continue
            blocked = False
            for j, other in enumerate(objects):
                if i == j:
                    continue
                occupied = {(r, c + other["dx"]) for r, c in other["cells"]}
                if candidate & occupied:
                    blocked = True
                    break
            if not blocked:
                obj["dx"] += 1
                changed = True

    out = [[0 for _ in range(w)] for _ in range(h)]
    for obj in objects:
        for r, c in obj["cells"]:
            out[r][c + obj["dx"]] = obj["color"]
    return out


